def load() -> pd.DataFrame:
    import geopandas as gpd
    path = 'data/wildfire/input/usa.gpkg'
    gdf = gpd.read_file(path, layer='usa_adm2')
    # Keep only needed attributes; geometry needed for spatial join later
    return gdf[['adm1_name','geometry']].rename(columns={'adm1_name':'state'})
